import type { JsonValue, Subject } from "./state.js";

export interface SubmitCommand {
  type: "submit";
  /** Generated by the service with the injected id generator. */
  requestId: string;
  requesterId: string;
  subject: Subject;
  payload: JsonValue;
  tenantId?: string;
}

export interface ApproveCommand {
  type: "approve";
  requestId: string;
  actorId: string;
  comment?: string;
}

export interface RejectCommand {
  type: "reject";
  requestId: string;
  actorId: string;
  comment?: string;
}

/** Hands the actor's pending task to a delegate (EC-25). */
export interface DelegateCommand {
  type: "delegate";
  requestId: string;
  actorId: string;
  taskId: string;
  toUserId: string;
  reason?: string;
}

/** Gives a blocked step to users chosen by an admin (EC-46). */
export interface ReassignStepCommand {
  type: "reassign";
  requestId: string;
  adminId: string;
  stepId: string;
  toUserIds: string[];
  reason: string;
  taskId?: never;
}

/** Moves one pending task to another user, chosen by an admin. */
export interface ReassignTaskCommand {
  type: "reassign";
  requestId: string;
  adminId: string;
  taskId: string;
  toUserId: string;
  reason: string;
  stepId?: never;
}

/** Resolves the approvers of a blocked step again, e.g. after the host fixed its data (EC-46). */
export interface RetryStepCommand {
  type: "retry";
  requestId: string;
  adminId: string;
  stepId: string;
}

/** Closes the whole request with an admin decision; every open task is cancelled (EC-18). */
export interface OverrideCommand {
  type: "override";
  requestId: string;
  adminId: string;
  decision: "approve" | "reject";
  reason: string;
}

export type Command =
  | SubmitCommand
  | ApproveCommand
  | RejectCommand
  | DelegateCommand
  | ReassignStepCommand
  | ReassignTaskCommand
  | RetryStepCommand
  | OverrideCommand;
